82	  if (!read_elf64_header(elf_path, buf, eh, err)) return "";
83	
84	  // Scan section headers for a symbol table; resolve names through its linked
85	  // string table (sh_link).
86	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
87	    Elf64_Shdr sym_sh;
88	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
