191	      if (ELF64_ST_TYPE(sym.st_info) != STT_FUNC) continue;
192	      if (sym.st_value > addr) continue;
193	      // With a size, require coverage; without, accept as a preceding label.
194	      if (sym.st_size != 0 && addr >= sym.st_value + sym.st_size) continue;
195	      if (found && sym.st_value <= best_value) continue;
