197	      const size_t noff = str_sh.sh_offset + sym.st_name;
198	      if (noff >= buf.size()) continue;
199	      const char* name = buf.data() + noff;
200	      const size_t avail = buf.size() - noff;
201	      if (::strnlen(name, avail) == avail) continue;
202	
203	      best_name = name;
204	      best_value = sym.st_value;
205	      found = true;
206	    }
207	  }
