146	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
147	// only the built-in qemu descriptor, so it resolves that directly rather than
148	// discover_engines(), which would spawn a --describe subprocess per Verilator
149	// build only to discard them all here.
150	int run_fast(const Cli& cli) {
151	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
152	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
153	    std::fprintf(stderr,
154	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
155	                 "got '%s'\n",
156	                 cli.engine.c_str());
157	    return 2;
158	  }
159	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
160	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
161	  std::string err;
162	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
163	  if (!err.empty()) {
164	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
165	    return 2;
166	  }
167	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
168	  if (cli.gdb) {
169	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
170	    extra.push_back("-gdb");
171	    extra.push_back("tcp::" + port);
172	    extra.push_back("-S");
173	  }
174	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
175	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
176	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
177	  // ELF -- the override is the user's call.
178	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
179	  int xlen = 64;
180	  if (cli.engine == kQemuId32) xlen = 32;
181	  else if (cli.engine == kQemuId64) xlen = 64;
182	  else if (elf_w) xlen = elf_w;  // no explicit engine: follow the ELF
183	  if (!cli.engine.empty() && elf_w && elf_w != xlen)
184	    std::fprintf(stderr,
185	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
186	                 "(running as rv%d)\n",
187	                 cli.engine.c_str(), xlen, elf_w, xlen);
188	  return run_standalone(cli, builtin_qemu_arch(xlen), "fast", extra);
189	}
