220	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
221	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
222	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
223	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
224	  const char* iceman = std::getenv("ICEMAN");
225	  if (!iceman || !*iceman) {
226	    std::fprintf(stderr,
227	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
228	                 "(export ICEMAN=<path to ICEman binary>)\n");
229	    return 2;
230	  }
231	  // Build vsim argv from the standalone template, appending user passthrough
232	  // and the JTAG port flag.
233	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
234	  if (elf.empty()) return 2;
235	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
236	  std::vector<std::string> vsim_pass = cli.passthrough;
237	  vsim_pass.push_back("--jtag-port");
238	  vsim_pass.push_back(jtag_port);
239	  std::string err;
240	  const std::vector<std::string> vsim_argv =
241	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
242	  if (!err.empty()) {
243	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
244	    return 2;
245	  }
246	  std::fprintf(stderr,
247	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
248	               jtag_port.c_str());
249	  if (fork_background(vsim_argv) < 0) {
250	    std::fprintf(stderr,
251	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
252	    return 1;
253	  }
254	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
255	  // Wait for the port to be LISTENing before launching the debugger (it does not
256	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
257	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
258	  // but launch anyway if it never appears.
259	  if (const int pnum = std::atoi(jtag_port.c_str());
260	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
261	    std::fprintf(stderr,
262	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
263	                 "after 20s; launching the debugger anyway\n",
264	                 jtag_port.c_str());
265	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
266	  // localhost, port 9104) instead of its default real-hardware adapter; without
267	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
268	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
269	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
270	}
