272	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
273	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
274	// engine's own output. Unlike fast, this must discover the Verilator build(s)
275	// to resolve the engine (explicit --engine, else the sole one).
276	int run_accurate(const Cli& cli) {
277	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
278	  // --describe subprocess per Verilator build only to fail on the argument.
279	  if (int rc = check_one_elf(cli, "cycle")) return rc;
280	  // --mem-size is validated but has nothing to size: the cycle engine always
281	  // models its full DRAM window. Say so instead of silently ignoring it.
282	  if (!cli.mem_size.empty()) {
283	    std::string se;
284	    if (parse_size(cli.mem_size, se); !se.empty()) {
285	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
286	                   se.c_str());
287	      return 2;
288	    }
289	    std::fprintf(stderr,
290	                 "[andesim] --mem-size: the cycle engine models its full "
291	                 "DRAM window; nothing to size\n");
292	  }
293	  Discovery disc = discover_engines();
294	  std::string err;
295	  const EngineDescriptor* eng =
296	      resolve_accurate_engine(disc.engines, cli.engine, err);
297	  if (!eng) {
298	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
299	    // Surface why an expected engine may be absent (failed --describe, etc.).
300	    for (const std::string& w : disc.warnings)
301	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
302	    return 2;
303	  }
304	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
305	  // vice versa) cannot run. Catch it here with a clear message instead of the
306	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
307	  // positional.
308	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
309	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
310	    return 2;
311	  }
312	  // --dry-run previews the standalone command and spawns nothing, so it takes
313	  // precedence over the interactive --gdb path (a dry run launches no debugger).
314	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
315	  return run_standalone(cli, *eng, "cycle");
316	}
